n  // References\n  tasks               Task[]\n  categories          Category[]\n  taskReminders       TaskReminder[]\n  goals               Goal[]\n  projects            Project[]\n  sentFriendReqs      FriendRequest[]         @relation(\"Requester\")\n  receivedFriendReqs  FriendRequest[]         @relation(\"Receiver\")\n  friends             Friend[]                @relation(\"UserFriends\")\n  friendOf            Friend[]                @relation(\"FriendOf\")\n  conversationMembers ConversationMember[]\n  sentMessages        Message[]\n  ownedStudyRooms     StudyRoom[]             @relation(\"RoomOwner\")\n  studyRoomMembers    StudyRoomMember[]\n  wallet              Wallet?\n  tokenTransactions   TokenTransaction[]\n  orders              Order[]\n  inventoryItems      InventoryItem[]\n  premiumSub          PremiumSubscription?\n  pet                 Pet?\n  pomodoroSessions    PomodoroSession[]\n  notifications       Notification[]\n  aiConversations     AiConversation[]\n  productivityStats   ProductivityStatistic[]\n  loginStreak         LoginStreak?\n  rewards             UserReward[]\n  sentNotifications   Notification[]          @relation(\"NotificationSender\")\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([email])\n  @@index([username])\n}\n\n// ============================================================\n// 2. TASKS\n// ============================================================\n\nmodel Category {\n  id     String  @id @default(uuid())\n  name   String\n  color  String  @default(\"#6C63FF\")\n  icon   String?\n  userId String\n  user   User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tasks  Task[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\nmodel Task {\n  id          String       @id @default(uuid())\n  title       String\n  description String?\n  priority    TaskPriority @default(MEDIUM)\n  status      TaskStatus   @default(PENDING)\n\n  // Scheduling\n  dueDate          DateTime?\n  startTime        String?\n  endTime          String?\n  estimatedMinutes Int       @default(0)\n  actualMinutes    Int       @default(0)\n\n  // Recurring\n  isRecurring      Boolean @default(false)\n  recurringPattern String? // e.g. \"DAILY\", \"WEEKLY:MON,WED\"\n\n  // Metadata\n  tags        String[]  @default([])\n  tokenReward Int       @default(5)\n  xpReward    Int       @default(10)\n  completedAt DateTime?\n\n  // Relations\n  userId           String\n  user             User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  categoryId       String?\n  category         Category?         @relation(fields: [categoryId], references: [id])\n  projectId        String?\n  project          Project?          @relation(fields: [projectId], references: [id])\n  subTasks         SubTask[]\n  reminders        TaskReminder[]\n  pomodoroSessions PomodoroSession[]\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([userId])\n  @@index([status])\n  @@index([dueDate])\n}\n\nmodel SubTask {\n  id          String  @id @default(uuid())\n  title       String\n  isCompleted Boolean @default(false)\n  taskId      String\n  task        Task    @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  sortOrder   Int     @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel TaskReminder {\n  id            String  @id @default(uuid())\n  minutesBefore Int // 60, 120, 180, 1440\n  isSent        Boolean @default(false)\n  taskId        String\n  task          Task    @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  userId        String\n  user          User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([taskId, minutesBefore])\n  @@index([taskId])\n}\n\nmodel Goal {\n  id          String    @id @default(uuid())\n  title       String\n  description String?\n  targetDate  DateTime?\n  isCompleted Boolean   @default(false)\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([userId])\n}\n\nmodel Project {\n  id          String  @id @default(uuid())\n  name        String\n  description String?\n  color       String  @default(\"#6C63FF\")\n  isArchived  Boolean @default(false)\n  userId      String\n  user        User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tasks       Task[]\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([userId])\n}\n\n// ============================================================\n// 3. FRIENDS\n// ============================================================\n\nmodel FriendRequest {\n  id          String              @id @default(uuid())\n  requesterId String\n  requester   User                @relation(\"Requester\", fields: [requesterId], references: [id], onDelete: Cascade)\n  receiverId  String\n  receiver    User                @relation(\"Receiver\", fields: [receiverId], references: [id], onDelete: Cascade)\n  status      FriendRequestStatus @default(PENDING)\n  message     String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([requesterId, receiverId])\n  @@index([receiverId])\n}\n\nmodel Friend {\n  id       String @id @default(uuid())\n  userId   String\n  user     User   @relation(\"UserFriends\", fields: [userId], references: [id], onDelete: Cascade)\n  friendId String\n  friend   User   @relation(\"FriendOf\", fields: [friendId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([userId, friendId])\n  @@index([userId])\n}\n\n// ============================================================\n// 4. CHAT\n// ============================================================\n\nmodel Conversation {\n  id            String               @id @default(uuid())\n  name          String?\n  type          ConversationType     @default(DIRECT)\n  avatarUrl     String?\n  members       ConversationMember[]\n  messages      Message[]\n  lastMessage   String?\n  lastMessageAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel ConversationMember {\n  id             String       @id @default(uuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  userId         String\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  isAdmin        Boolean      @default(false)\n  lastReadAt     DateTime?\n  joinedAt       DateTime     @default(now())\n\n  @@unique([conversationId, userId])\n  @@index([userId])\n}\n\nmodel Message {\n  id             String       @id @default(uuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  senderId       String\n  sender         User         @relation(fields: [senderId], references: [id], onDelete: Cascade)\n  content        String\n  type           MessageType  @default(TEXT)\n  fileUrl        String?\n  isRead         Boolean      @default(false)\n  isDeleted      Boolean      @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([conversationId])\n  @@index([senderId])\n}\n\n// ============================================================\n// 5. STUDY ROOMS\n// ============================================================\n\nmodel StudyRoom {\n  id              String            @id @default(uuid())\n  name            String\n  description     String?\n  avatarUrl       String?\n  ownerId         String\n  owner           User              @relation(\"RoomOwner\", fields: [ownerId], references: [id], onDelete: Cascade)\n  members         StudyRoomMember[]\n  maxParticipants Int               @default(10)\n  isPrivate       Boolean           @default(false)\n  inviteCode      String?           @unique\n  status          StudyRoomStatus   @default(ACTIVE)\n  expiresAt       DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([ownerId])\n  @@index([inviteCode])\n}\n\nmodel StudyRoomMember {\n  id       String    @id @default(uuid())\n  roomId   String\n  room     StudyRoom @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  userId   String\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  isAdmin  Boolean   @default(false)\n  joinedAt DateTime  @default(now())\n\n  @@unique([roomId, userId])\n  @@index([userId])\n}\n\n// ============================================================\n// 6. SHOP\n// ============================================================\n\nmodel ProductCategory {\n  id          String    @id @default(uuid())\n  name        String    @unique\n  description String?\n  iconUrl     String?\n  products    Product[]\n  sortOrder   Int       @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Product {\n  id             String          @id @default(uuid())\n  name           String\n  description    String?\n  imageUrl       String?\n  price          Int // in TOKENS\n  categoryId     String\n  category       ProductCategory @relation(fields: [categoryId], references: [id])\n  rarity         Rarity          @default(COMMON)\n  stock          Int             @default(-1) // -1 = unlimited\n  discountPct    Int             @default(0) // 0-100\n  isAvailable    Boolean         @default(true)\n  isPremiumOnly  Boolean         @default(false)\n  orderItems     OrderItem[]\n  inventoryItems InventoryItem[]\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([categoryId])\n  @@index([isAvailable])\n}\n\n// ============================================================\n// 7. WALLET & TOKENS\n// ============================================================\n\nmodel Wallet {\n  id           String             @id @default(uuid())\n  userId       String             @unique\n  user         User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  balance      Int                @default(0) // authoritative token balance\n  transactions TokenTransaction[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel TokenTransaction {\n  id           String               @id @default(uuid())\n  userId       String\n  user         User                 @relation(fields: [userId], references: [id], onDelete: Cascade)\n  walletId     String\n  wallet       Wallet               @relation(fields: [walletId], references: [id])\n  type         TokenTransactionType\n  amount       Int // positive = credit, negative = debit\n  balanceAfter Int\n  description  String?\n  referenceId  String? // order id, task id, etc.\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([walletId])\n  @@index([type])\n}\n\n// ============================================================\n// 8. ORDERS\n// ============================================================\n\nmodel Order {\n  id          String      @id @default(uuid())\n  userId      String\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  totalTokens Int\n  status      OrderStatus @default(PENDING)\n  items       OrderItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\nmodel OrderItem {\n  id          String  @id @default(uuid())\n  orderId     String\n  order       Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId   String\n  product     Product @relation(fields: [productId], references: [id])\n  quantity    Int     @default(1)\n  priceAtSale Int // token price at time of purchase\n\n  @@index([orderId])\n}\n\n// ============================================================\n// 9. INVENTORY\n// ============================================================\n\nmodel InventoryItem {\n  id         String  @id @default(uuid())\n  userId     String\n  user       User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId  String\n  product    Product @relation(fields: [productId], references: [id])\n  quantity   Int     @default(1)\n  isEquipped Boolean @default(false)\n\n  acquiredAt DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([userId, productId])\n  @@index([userId])\n}\n\n// ============================================================\n// 10. PREMIUM SUBSCRIPTIONS\n// ============================================================\n\nmodel PremiumSubscription {\n  id          String             @id @default(uuid())\n  userId      String             @unique\n  user        User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  plan        String // \"MONTHLY\" | \"YEARLY\"\n  status      SubscriptionStatus @default(ACTIVE)\n  startDate   DateTime           @default(now())\n  endDate     DateTime\n  autoRenew   Boolean            @default(false)\n  referenceId String? // payment reference\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([endDate])\n}\n\n// ============================================================\n// 11. VIRTUAL PET\n// ============================================================\n\nmodel Pet {\n  id           String         @id @default(uuid())\n  userId       String         @unique\n  user         User           @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name         String\n  type         PetType        @default(CAT)\n  level        Int            @default(1)\n  xp           Int            @default(0)\n  hunger       Int            @default(100) // 0-100\n  happiness    Int            @default(100) // 0-100\n  energy       Int            @default(100) // 0-100\n  avatarUrl    String?\n  petInventory PetInventory[]\n\n  lastFedAt    DateTime?\n  lastPlayedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel PetItem {\n  id           String         @id @default(uuid())\n  name         String\n  description  String?\n  imageUrl     String?\n  type         String // \"FOOD\" | \"TOY\" | \"CLOTHES\" | \"ACCESSORY\"\n  effectType   String? // \"HUNGER\" | \"HAPPINESS\" | \"ENERGY\"\n  effectValue  Int            @default(0)\n  price        Int // in TOKENS\n  rarity       Rarity         @default(COMMON)\n  petInventory PetInventory[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel PetInventory {\n  id         String  @id @default(uuid())\n  petId      String\n  pet        Pet     @relation(fields: [petId], references: [id], onDelete: Cascade)\n  itemId     String\n  item       PetItem @relation(fields: [itemId], references: [id])\n  quantity   Int     @default(1)\n  isEquipped Boolean @default(false)\n\n  acquiredAt DateTime @default(now())\n\n  @@unique([petId, itemId])\n  @@index([petId])\n}\n\n// ============================================================\n// 12. POMODORO SESSIONS\n// ============================================================\n\nmodel PomodoroSession {\n  id                String    @id @default(uuid())\n  userId            String\n  user              User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  taskId            String?\n  task              Task?     @relation(fields: [taskId], references: [id])\n  focusMinutes      Int       @default(25)\n  breakMinutes      Int       @default(5)\n  sessionsPlanned   Int       @default(4)\n  sessionsCompleted Int       @default(0)\n  isCompleted       Boolean   @default(false)\n  xpEarned          Int       @default(0)\n  tokenEarned       Int       @default(0)\n  startedAt         DateTime  @default(now())\n  endedAt           DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([taskId])\n}\n\n// ============================================================\n// 13. NOTIFICATIONS\n// ============================================================\n\nmodel Notification {\n  id          String           @id @default(uuid())\n  userId      String\n  user        User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  senderId    String?\n  sender      User?            @relation(\"NotificationSender\", fields: [senderId], references: [id])\n  type        NotificationType\n  title       String\n  body        String\n  data        Json? // extra payload (taskId, roomId, etc.)\n  isRead      Boolean          @default(false)\n  scheduledAt DateTime? // for future scheduled notifications\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([isRead])\n}\n\n// ============================================================\n// 14. AI\n// ============================================================\n\nmodel AiConversation {\n  id       String      @id @default(uuid())\n  userId   String\n  user     User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title    String?\n  messages AiMessage[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\nmodel AiMessage {\n  id             String         @id @default(uuid())\n  conversationId String\n  conversation   AiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  role           String // \"user\" | \"assistant\"\n  content        String\n  metadata       Json? // extracted task info, plan, etc.\n\n  createdAt DateTime @default(now())\n\n  @@index([conversationId])\n}\n\n// ============================================================\n// 15. PRODUCTIVITY STATISTICS\n// ============================================================\n\nmodel ProductivityStatistic {\n  id               String   @id @default(uuid())\n  userId           String\n  user             User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  date             DateTime @db.Date\n  tasksCreated     Int      @default(0)\n  tasksCompleted   Int      @default(0)\n  tasksCancelled   Int      @default(0)\n  focusMinutes     Int      @default(0) // total pomodoro focus time\n  pomodoroSessions Int      @default(0)\n  tokensEarned     Int      @default(0)\n  tokensSpent      Int      @default(0)\n  xpEarned         Int      @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, date])\n  @@index([userId])\n  @@index([date])\n}\n\n// ============================================================\n// 16. LOGIN STREAKS & REWARDS\n// ============================================================\n\nmodel LoginStreak {\n  id            String    @id @default(uuid())\n  userId        String    @unique\n  user          User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  currentStreak Int       @default(0)\n  longestStreak Int       @default(0)\n  lastLoginDate DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Reward {\n  id          String       @id @default(uuid())\n  name        String\n  description String?\n  type        String // \"TOKEN\" | \"ITEM\" | \"PREMIUM\" | \"BADGE\"\n  value       Int          @default(0) // token amount or item id\n  streakDay   Int? // day 1, 3, 7, 14, 30 — nullable for non-streak rewards\n  imageUrl    String?\n  isActive    Boolean      @default(true)\n  userRewards UserReward[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel UserReward {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  rewardId  String\n  reward    Reward   @relation(fields: [rewardId], references: [id], onDelete: Cascade)\n  claimedAt DateTime @default(now())\n\n  @@unique([userId, rewardId])\n  @@index([userId])\n}\n",
